public sealed interface Device permits Laptop, SmartPhone {}

public record Laptop(String model, int ramGb) implements Device {}
public record SmartPhone(String model, boolean has5G) implements Device {}

public class DeviceManager {
    public void configureDevice(Device device) {
        // 1. Pattern matching with conditional-AND (&&) using flow scoping
        if (device instanceof Laptop laptop && laptop.ramGb() >= 16) {
            System.out.println("Configuring high-performance laptop: " + laptop.model());
        } 
        // 2. Flow scoping with early return / inversion
        else if (!(device instanceof SmartPhone phone)) {
            // 'phone' is NOT in scope here because the check failed
            System.out.println("Unknown device type.");
        } 
        else {
            // 'phone' IS in scope here because the negation of false is true
            System.out.println("Configuring phone: " + phone.model() + " (5G: " + phone.has5G() + ")");
        }
    }
}
